/* User supplied rule text is data, never executable code. */
(()=>{'use strict';const KEY='kp-master-custom-rules-v1',$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const supplied=JSON.parse($('kp-event-rule-data').textContent).rules;let custom=[],dialog,selected=null;
function validate(rows){if(!Array.isArray(rows)||rows.length>2000)throw Error('Invalid rules backup.');return rows.map(r=>{if(typeof r.id!=='string'||r.id.length>100||typeof r.title!=='string'||!r.title.trim()||r.title.length>200||typeof r.text!=='string'||!r.text.trim()||r.text.length>100000)throw Error('Invalid rule title or text.');return {id:r.id,title:r.title,topic:String(r.topic||'Other').slice(0,100),text:r.text,custom:true};});}
try{custom=validate(JSON.parse(localStorage.getItem(KEY)||'[]'));}catch(_){}
function all(){const map=new Map(supplied.map(r=>[r.id,{...r}]));for(const r of custom)map.set(r.id,{...r});return [...map.values()].sort((a,b)=>a.title.localeCompare(b.title));}
function persist(){localStorage.setItem(KEY,JSON.stringify(custom));}
function snapshot(){return {version:1,custom:structuredClone(custom)};}
function restore(data){const rows=validate(data?.custom);localStorage.setItem(KEY,JSON.stringify(rows));custom=rows;if(dialog)list();}
function filter(){const q=dialog.querySelector('[data-search]').value.trim().toLowerCase(),topic=dialog.querySelector('[data-topic]').value;return all().filter(r=>(!topic||r.topic===topic)&&(!q||(r.title+' '+r.text).toLowerCase().includes(q)));}
function list(){const rows=filter(),select=dialog.querySelector('[data-list]');select.replaceChildren(...rows.map(r=>{const n=document.createElement('option');n.value=r.id;n.textContent=r.title+(r.custom?' · saved edit':'');return n;}));if(rows.some(r=>r.id===selected))select.value=selected;else selected=rows[0]?.id||null;select.value=selected||'';show();dialog.querySelector('[data-count]').textContent=rows.length+' / '+all().length+' rules';}
function show(){const row=all().find(r=>r.id===selected);dialog.querySelector('[data-title]').value=row?.title||'';dialog.querySelector('[data-rule-topic]').value=row?.topic||'Other';dialog.querySelector('[data-text]').value=row?.text||'';dialog.querySelector('[data-rule-status]').textContent=row?(row.custom?'Saved on this computer.':'Supplied reference · '+row.source):'Enter a title, topic and rule text.';}
function save(){try{const row=validate([{id:selected||'custom-'+crypto.randomUUID(),title:dialog.querySelector('[data-title]').value.trim(),topic:dialog.querySelector('[data-rule-topic]').value.trim(),text:dialog.querySelector('[data-text]').value.trim()}])[0],next=custom.filter(r=>r.id!==row.id).concat(row);localStorage.setItem(KEY,JSON.stringify(next));custom=next;selected=row.id;dialog.querySelector('[data-search]').value='';dialog.querySelector('[data-topic]').value='';list();dialog.querySelector('[data-rule-status]').textContent='Rule saved. Included in chart backups and Export rules backup.';}catch(e){dialog.querySelector('[data-rule-status]').textContent=e.message;}}
function printable(rows){return rows.map((r,i)=>'<article style="break-before:'+(i?'page':'auto')+'"><h2>'+esc(r.title)+'</h2><p>'+esc(r.topic)+'</p><div style="white-space:pre-wrap;overflow-wrap:anywhere">'+esc(r.text)+'</div></article>').join('');}
function download(){const data={version:1,exportedAt:new Date().toISOString(),rules:all(),custom:structuredClone(custom)},url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='KP-MASTER-Rules-Backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function open(){if(!dialog){dialog=document.createElement('dialog');dialog.className='kp-rules-dialog';dialog.innerHTML='<header><h2>Rules · नियम</h2><button data-close aria-label="Close rules">×</button></header><div class="kp-rules-actions"><input type="search" data-search placeholder="Search rules or text" aria-label="Search rules"><select data-topic aria-label="Filter topic"><option value="">All topics</option></select><button data-new>Add New Rule</button><button data-backup>Export rules backup</button><label class="kp-rule-import">Import backup<input type="file" data-import accept=".json,application/json"></label></div><p data-count></p><div class="kp-rules-grid"><select data-list size="18" aria-label="Rules list"></select><div class="kp-rule-editor"><label>Rule title<input data-title maxlength="200"></label><label>Topic<input data-rule-topic maxlength="100"></label><label>Rule text<textarea data-text rows="18" maxlength="100000"></textarea></label><p data-rule-status role="status"></p><div class="kp-rules-actions"><button data-save>Save Rule</button><button data-print>Preview / Print selected rule</button><button data-print-all>Preview / Print filtered rules</button></div></div></div>';document.body.append(dialog);for(const topic of [...new Set(supplied.map(r=>r.topic))].sort()){const n=document.createElement('option');n.value=n.textContent=topic;dialog.querySelector('[data-topic]').append(n);}dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.querySelector('[data-search]').oninput=list;dialog.querySelector('[data-topic]').onchange=list;dialog.querySelector('[data-list]').onchange=e=>{selected=e.target.value;show();};dialog.querySelector('[data-new]').onclick=()=>{selected=null;show();dialog.querySelector('[data-title]').focus();};dialog.querySelector('[data-save]').onclick=save;dialog.querySelector('[data-backup]').onclick=download;dialog.querySelector('[data-import]').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>10000000)throw Error('Rules backup is too large.');const data=JSON.parse(await file.text()),rows=validate(data.custom);const merged=new Map(custom.map(r=>[r.id,r]));rows.forEach(r=>merged.set(r.id,r));restore({custom:[...merged.values()]});dialog.querySelector('[data-rule-status]').textContent='Rules backup imported.';}catch(err){dialog.querySelector('[data-rule-status]').textContent=err.message;}e.target.value='';};dialog.querySelector('[data-print]').onclick=()=>{const row=all().find(r=>r.id===selected);if(row)KPChartWorkspace.printable('KP Master · Rules',printable([row]));};dialog.querySelector('[data-print-all]').onclick=()=>KPChartWorkspace.printable('KP Master · Rules',printable(filter()));}
list();dialog.showModal();}
const oldSave=window.getChartData;if(oldSave)window.getChartData=function(...args){return {...oldSave.apply(this,args),predictionRules:snapshot()};};const oldRestore=window.restoreChartData;if(oldRestore)window.restoreChartData=function(data,...args){if(data?.predictionRules)validate(data.predictionRules.custom);const result=oldRestore.call(this,data,...args);if(data?.predictionRules)restore(data.predictionRules);return result;};
function init(){for(const target of [document.querySelector('.kp-quick-tools'),$('prediction')?.querySelector('.pred-compact-topbar'),$('resources')?.querySelector('.card')].filter(Boolean)){const b=document.createElement('button');b.type='button';b.textContent='Rules';b.className='kp-rules-button';b.onclick=open;target.append(b);}}
window.KPRules=Object.freeze({open,all,snapshot,restore,exportBackup:download});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(init,250));else init();})();
